/**
 * OpenClaw WITH Goal Autonomy - GoalTree Implementation
 * Based on SelfGoal paper (arXiv 2406.04784)
 */

export interface GoalNode {
  id: string;
  goal: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  parent: string | null;
  children: string[];
  priority: number;
  createdAt: number;
  lastUpdated: number;

  // SelfGoal: Usefulness tracking
  usefulnessScore: number;
  depth: number;
  attempts: number;
  successRate: number;
}

export interface GoalContext {
  currentState: string;
  recentEvents: string[];
  availableTools: string[];
  timeSinceLastAction: number;
}

export class GoalTree {
  private nodes: Map<string, GoalNode> = new Map();
  private root: string | null = null;
  private maxDepth: number = 5;

  constructor(initialGoal?: string) {
    if (initialGoal) {
      this.root = this.createNode(initialGoal, null);
    }
  }

  /**
   * SelfGoal: Search Module
   * Find most useful subgoal for current context
   */
  findMostUsefulSubgoal(context: GoalContext): GoalNode | null {
    const leafNodes = Array.from(this.nodes.values())
      .filter(n => n.children.length === 0 && n.status === 'pending');

    if (leafNodes.length === 0) {
      return null;
    }

    // Score by usefulness * priority * (1 - attempts * 0.1)
    const scored = leafNodes.map(node => ({
      node,
      score: node.usefulnessScore * node.priority * Math.max(0.1, 1 - node.attempts * 0.1)
    }));

    scored.sort((a, b) => b.score - a.score);

    return scored[0].node;
  }

  /**
   * SelfGoal: Decompose Module
   * Break down goal into subgoals
   */
  async decomposeGoal(nodeId: string, subgoals: string[]): Promise<GoalNode[]> {
    const parent = this.nodes.get(nodeId);
    if (!parent) {
      throw new Error(`Node ${nodeId} not found`);
    }

    if (parent.depth >= this.maxDepth) {
      console.log(`Max depth ${this.maxDepth} reached, cannot decompose further`);
      return [];
    }

    const newNodes: GoalNode[] = [];

    for (const subgoalText of subgoals) {
      // Filter: Check uniqueness (SelfGoal pattern)
      if (this.isDuplicate(subgoalText)) {
        continue;
      }

      const child = this.createNode(subgoalText, nodeId);
      newNodes.push(child);
    }

    return newNodes;
  }

  /**
   * SelfGoal: Progressive updating
   * Track usefulness based on success/failure
   */
  updateUsefulness(nodeId: string, success: boolean): void {
    const node = this.nodes.get(nodeId);
    if (!node) return;

    // Update success rate
    const totalAttempts = node.attempts + 1;
    const successfulAttempts = node.successRate * node.attempts + (success ? 1 : 0);
    node.successRate = successfulAttempts / totalAttempts;
    node.attempts = totalAttempts;
    node.lastUpdated = Date.now();

    // Update usefulness score
    node.usefulnessScore = node.successRate * node.priority;

    // Propagate to parent
    if (node.parent) {
      this.propagateUsefulness(node.parent);
    }
  }

  private propagateUsefulness(nodeId: string): void {
    const node = this.nodes.get(nodeId);
    if (!node) return;

    if (node.children.length > 0) {
      const children = node.children.map(id => this.nodes.get(id)!).filter(Boolean);
      const avgChildUsefulness = children.reduce((sum, c) => sum + c.usefulnessScore, 0) / children.length;
      node.usefulnessScore = avgChildUsefulness * node.priority;
      node.lastUpdated = Date.now();
    }

    if (node.parent) {
      this.propagateUsefulness(node.parent);
    }
  }

  private createNode(goal: string, parentId: string | null): GoalNode {
    const parent = parentId ? this.nodes.get(parentId) : null;

    const node: GoalNode = {
      id: `goal-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      goal,
      status: 'pending',
      parent: parentId,
      children: [],
      priority: 0.5,
      createdAt: Date.now(),
      lastUpdated: Date.now(),
      usefulnessScore: 0.5,
      depth: parent ? parent.depth + 1 : 0,
      attempts: 0,
      successRate: 0.5
    };

    this.nodes.set(node.id, node);

    if (parent) {
      parent.children.push(node.id);
    }

    return node;
  }

  private isDuplicate(goalText: string): boolean {
    const normalized = goalText.toLowerCase().trim();
    for (const node of this.nodes.values()) {
      if (node.goal.toLowerCase().trim() === normalized) {
        return true;
      }
    }
    return false;
  }

  getNode(id: string): GoalNode | undefined {
    return this.nodes.get(id);
  }

  getAllNodes(): GoalNode[] {
    return Array.from(this.nodes.values());
  }

  getRoot(): GoalNode | null {
    return this.root ? this.nodes.get(this.root) || null : null;
  }
}

/**
 * Intrinsic Motivation System
 * Based on Sophia paper (System 3 meta-layer)
 */

export type DriveType = 'curiosity' | 'competence' | 'novelty' | 'autonomy';

export interface IntrinsicDrive {
  type: DriveType;
  level: number;
  threshold: number;
  lastTriggered: number;
  cooldownMs: number;
}

export interface MotivationEvent {
  type: 'surprise' | 'success' | 'novelty' | 'self_initiated';
  timestamp: number;
  impact: number;
}

export class IntrinsicMotivationSystem {
  private drives: Map<DriveType, IntrinsicDrive> = new Map([
    ['curiosity', {
      type: 'curiosity',
      level: 0,
      threshold: 0.7,
      lastTriggered: 0,
      cooldownMs: 3600000 // 1 hour
    }],
    ['competence', {
      type: 'competence',
      level: 0,
      threshold: 0.6,
      lastTriggered: 0,
      cooldownMs: 7200000 // 2 hours
    }],
    ['novelty', {
      type: 'novelty',
      level: 0,
      threshold: 0.5,
      lastTriggered: 0,
      cooldownMs: 10800000 // 3 hours
    }],
    ['autonomy', {
      type: 'autonomy',
      level: 0,
      threshold: 0.8,
      lastTriggered: 1,
      cooldownMs: 14400000 // 4 hours
    }]
  ]);

  /**
   * Update drive levels based on events
   */
  updateDrives(event: MotivationEvent): void {
    const now = Date.now();

    switch (event.type) {
      case 'surprise':
        // Bayesian surprise → curiosity
        const curiosity = this.drives.get('curiosity')!;
        curiosity.level = Math.min(1.0, curiosity.level + event.impact);
        break;

      case 'success':
        // Successful task → competence
        const competence = this.drives.get('competence')!;
        competence.level = Math.min(1.0, competence.level + event.impact);
        break;

      case 'novelty':
        // New tool/skill → novelty
        const novelty = this.drives.get('novelty')!;
        novelty.level = Math.min(1.0, novelty.level + event.impact);
        break;

      case 'self_initiated':
        // Self-initiated action → autonomy
        const autonomy = this.drives.get('autonomy')!;
        autonomy.level = Math.min(1.0, autonomy.level + event.impact);
        break;
    }
  }

  /**
   * Check if any drive should trigger goal generation
   */
  checkAndGenerateGoals(): Array<{ drive: DriveType; level: number }> {
    const now = Date.now();
    const triggered: Array<{ drive: DriveType; level: number }> = [];

    for (const [type, drive] of this.drives) {
      const timeSinceLast = now - drive.lastTriggered;

      if (drive.level >= drive.threshold && timeSinceLast >= drive.cooldownMs) {
        triggered.push({ drive: type, level: drive.level });

        // Reset after triggering
        drive.level = 0;
        drive.lastTriggered = now;
      }
    }

    return triggered;
  }

  /**
   * Generate goal based on drive type
   */
  generateGoalFromDrive(drive: DriveType): string {
    switch (drive) {
      case 'curiosity':
        return 'Explore and investigate unexpected patterns in recent events';
      case 'competence':
        return 'Improve proficiency in frequently used skills';
      case 'novelty':
        return 'Experiment with new approaches or tools not yet tried';
      case 'autonomy':
        return 'Take initiative on self-directed improvement project';
      default:
        return 'General improvement goal';
    }
  }

  /**
   * Get current drive levels (for monitoring)
   */
  getDriveLevels(): Map<DriveType, number> {
    const levels = new Map<DriveType, number>();
    for (const [type, drive] of this.drives) {
      levels.set(type, drive.level);
    }
    return levels;
  }

  /**
   * Decay drive levels over time (call periodically)
   */
  decayDrives(decayFactor: number = 0.1): void {
    for (const drive of this.drives.values()) {
      drive.level = Math.max(0, drive.level * (1 - decayFactor));
    }
  }
}

/**
 * Goal Archive with Rollback
 * Based on Darwin Gödel Machine paper (arXiv 2505.22954)
 */

export interface GoalAttempt {
  id: string;
  goalId: string;
  goalText: string;
  timestamp: number;
  context: string;
  actions: string[];
  result: 'success' | 'failure' | 'partial';
  parentAttempt: string | null;
  children: string[];
  interestingScore: number;
  lessons: string[];
}

export interface GoalPattern {
  id: string;
  pattern: string;
  successCount: number;
  failureCount: number;
  lastSeen: number;
  examples: string[];
}

export class GoalArchive {
  private attempts: Map<string, GoalAttempt> = new Map();
  private patterns: Map<string, GoalPattern> = new Map();
  private maxAttempts: number = 1000;
  private maxPatterns: number = 100;

  /**
   * Record a goal attempt (success or failure)
   */
  recordAttempt(
    goalId: string,
    goalText: string,
    context: string,
    actions: string[],
    success: boolean,
    lessons: string[] = []
  ): GoalAttempt {
    const attempt: GoalAttempt = {
      id: `attempt-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      goalId,
      goalText,
      timestamp: Date.now(),
      context,
      actions,
      result: success ? 'success' : 'failure',
      parentAttempt: this.findParentAttempt(goalId),
      children: [],
      interestingScore: this.calculateInterestingness(goalText, success),
      lessons
    };

    // Store attempt
    this.attempts.set(attempt.id, attempt);

    // Link to parent
    if (attempt.parentAttempt) {
      const parent = this.attempts.get(attempt.parentAttempt);
      if (parent) {
        parent.children.push(attempt.id);
      }
    }

    // Extract patterns if successful
    if (success) {
      this.extractPattern(attempt);
    }

    // Cleanup old attempts if needed
    if (this.attempts.size > this.maxAttempts) {
      this.cleanupOldAttempts();
    }

    return attempt;
  }

  /**
   * Find previous successful attempt for rollback
   */
  findPreviousSuccess(goalId: string): GoalAttempt | null {
    const attempts = Array.from(this.attempts.values())
      .filter(a => a.goalId === goalId && a.result === 'success')
      .sort((a, b) => b.timestamp - a.timestamp);

    return attempts[0] || null;
  }

  /**
   * Find interesting attempts for exploration (DGM pattern)
   */
  findInterestingAttempts(limit: number = 5): GoalAttempt[] {
    const attempts = Array.from(this.attempts.values())
      .sort((a, b) => b.interestingScore - a.interestingScore);

    return attempts.slice(0, limit);
  }

  /**
   * Get patterns for a goal type
   */
  getPatternsForGoal(goalText: string): GoalPattern[] {
    const normalized = goalText.toLowerCase().trim();
    const matchingPatterns: GoalPattern[] = [];

    for (const pattern of this.patterns.values()) {
      if (normalized.includes(pattern.pattern.toLowerCase())) {
        matchingPatterns.push(pattern);
      }
    }

    return matchingPatterns.sort((a, b) => b.successCount - a.successCount);
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalAttempts: number;
    successRate: number;
    patternsLearned: number;
    interestingAttempts: number;
  } {
    const attempts = Array.from(this.attempts.values());
    const successes = attempts.filter(a => a.result === 'success').length;

    return {
      totalAttempts: attempts.length,
      successRate: attempts.length > 0 ? successes / attempts.length : 0,
      patternsLearned: this.patterns.size,
      interestingAttempts: attempts.filter(a => a.interestingScore > 0.7).length
    };
  }

  private findParentAttempt(goalId: string): string | null {
    // Find most recent attempt for same goal
    const attempts = Array.from(this.attempts.values())
      .filter(a => a.goalId === goalId)
      .sort((a, b) => b.timestamp - a.timestamp);

    return attempts[0]?.id || null;
  }

  private calculateInterestingness(goalText: string, success: boolean): number {
    // Higher score for:
    // - Successful attempts
    // - Novel goal types
    // - Recent attempts
    const successBonus = success ? 0.3 : 0;
    const noveltyBonus = this.isNovelGoal(goalText) ? 0.2 : 0;
    const baseScore = 0.0;

    return Math.min(1.0, baseScore + successBonus + noveltyBonus);
  }

  private isNovelGoal(goalText: string): boolean {
    const similar = Array.from(this.attempts.values())
      .filter(a => a.goalText.toLowerCase().includes(goalText.toLowerCase().substring(0, 20)));

    return similar.length < 3;
  }

  private extractPattern(attempt: GoalAttempt): void {
    // Extract pattern from successful attempt
    const patternKey = this.extractPatternKey(attempt);

    if (!patternKey) return;

    let pattern = this.patterns.get(patternKey);

    if (!pattern) {
      pattern = {
        id: `pattern-${Date.now()}`,
        pattern: patternKey,
        successCount: 0,
        failureCount: 0,
        lastSeen: Date.now(),
        examples: []
      };
      this.patterns.set(patternKey, pattern);
    }

    pattern.successCount++;
    pattern.lastSeen = Date.now();
    if (pattern.examples.length < 5) {
      pattern.examples.push(attempt.goalText);
    }

    // Cleanup old patterns if needed
    if (this.patterns.size > this.maxPatterns) {
      this.cleanupOldPatterns();
    }
  }

  private extractPatternKey(attempt: GoalAttempt): string | null {
    // Simple pattern extraction: key phrases
    const text = attempt.goalText.toLowerCase();

    if (text.includes('test')) return 'testing';
    if (text.includes('fix') || text.includes('bug')) return 'bugfix';
    if (text.includes('optim')) return 'optimization';
    if (text.includes('document')) return 'documentation';
    if (text.includes('monitor')) return 'monitoring';
    if (text.includes('security')) return 'security';

    return null;
  }

  private cleanupOldAttempts(): void {
    const attempts = Array.from(this.attempts.values())
      .sort((a, b) => b.timestamp - a.timestamp);

    // Keep most recent 800
    const toDelete = attempts.slice(800);
    for (const attempt of toDelete) {
      this.attempts.delete(attempt.id);
    }
  }

  private cleanupOldPatterns(): void {
    const patterns = Array.from(this.patterns.values())
      .sort((a, b) => b.lastSeen - a.lastSeen);

    // Keep most recent 80
    const toDelete = patterns.slice(80);
    for (const pattern of toDelete) {
      this.patterns.delete(pattern.id);
    }
  }
}

/**
 * Goal Generation Engine
 * Main orchestrator combining GoalTree + IntrinsicMotivation + Archive
 */

import { GoalTree, GoalNode, GoalContext } from './goal-tree.js';
import { IntrinsicMotivationSystem, DriveType } from './intrinsic-motivation.js';
import { GoalArchive, GoalAttempt } from './goal-archive.js';

export interface GoalEngineConfig {
  maxGoalsPerHeartbeat: number;
  maxActiveGoals: number;
  enableLearning: boolean;
  enableArchive: boolean;
}

export class GoalGenerationEngine {
  private goalTree: GoalTree;
  private motivation: IntrinsicMotivationSystem;
  private archive: GoalArchive;
  private config: GoalEngineConfig;

  private activeGoals: Set<string> = new Set();
  private completedGoals: number = 0;
  private failedGoals: number = 0;

  constructor(config: Partial<GoalEngineConfig> = {}) {
    this.config = {
      maxGoalsPerHeartbeat: 3,
      maxActiveGoals: 10,
      enableLearning: true,
      enableArchive: true,
      ...config
    };

    this.goalTree = new GoalTree();
    this.motivation = new IntrinsicMotivationSystem();
    this.archive = new GoalArchive();
  }

  /**
   * Main loop: Called on heartbeat or idle periods
   */
  async generateAndPursueGoals(context: GoalContext): Promise<{
    generated: number;
    executed: number;
    completed: number;
  }> {
    const result = {
      generated: 0,
      executed: 0,
      completed: 0
    };

    // Step 1: Check intrinsic motivation (Sophia pattern)
    const triggeredDrives = this.motivation.checkAndGenerateGoals();

    // Step 2: Generate goals from motivation
    for (const { drive, level } of triggeredDrives) {
      if (this.activeGoals.size >= this.config.maxActiveGoals) {
        break;
      }

      const goalText = this.motivation.generateGoalFromDrive(drive);
      const goal = this.goalTree.addNode(goalText, null);

      if (goal) {
        this.activeGoals.add(goal.id);
        result.generated++;

        // Decompose into subgoals
        await this.decomposeIfNeeded(goal.id, context);
      }
    }

    // Step 3: Find most useful subgoal (SelfGoal Search Module)
    const nextGoal = this.goalTree.findMostUsefulSubgoal(context);

    if (nextGoal) {
      // Step 4: Execute goal (SelfGoal Act Module)
      const success = await this.executeGoal(nextGoal, context);
      result.executed++;

      if (success) {
        result.completed++;
        this.completedGoals++;
        this.activeGoals.delete(nextGoal.id);

        // Update motivation (success → competence)
        this.motivation.updateDrives({
          type: 'success',
          timestamp: Date.now(),
          impact: 0.1
        });
      }

      // Step 5: Archive result (DGM pattern)
      if (this.config.enableArchive) {
        this.archive.recordAttempt(
          nextGoal.id,
          nextGoal.goal,
          context.currentState,
          [], // actions would be filled during execution
          success,
          [] // lessons would be extracted during execution
        );
      }

      // Update usefulness in tree
      this.goalTree.updateUsefulness(nextGoal.id, success);
    }

    // Decay drives over time
    this.motivation.decayDrives(0.05);

    return result;
  }

  /**
   * Add external goal (from user or plan)
   */
  addExternalGoal(goalText: string, priority: number = 0.5): GoalNode | null {
    if (this.activeGoals.size >= this.config.maxActiveGoals) {
      return null;
    }

    const goal = this.goalTree.addNode(goalText, null);
    if (goal) {
      this.activeGoals.add(goal.id);
      // Adjust priority
      goal.priority = priority;
    }

    return goal;
  }

  /**
   * Get current stats
   */
  getStats(): {
    activeGoals: number;
    completedGoals: number;
    failedGoals: number;
    archiveStats: ReturnType<GoalArchive['getStats']>;
    driveLevels: Map<DriveType, number>;
  } {
    return {
      activeGoals: this.activeGoals.size,
      completedGoals: this.completedGoals,
      failedGoals: this.failedGoals,
      archiveStats: this.archive.getStats(),
      driveLevels: this.motivation.getDriveLevels()
    };
  }

  private async decomposeIfNeeded(nodeId: string, context: GoalContext): Promise<void> {
    const node = this.goalTree.getNode(nodeId);
    if (!node) return;

    // Check if goal is too vague (needs decomposition)
    if (this.needsDecomposition(node)) {
      // LLM would generate subgoals here
      // For now, use simple decomposition
      const subgoals = await this.generateSubgoals(node.goal, context);

      for (const subgoalText of subgoals) {
        this.goalTree.addNode(subgoalText, nodeId);
      }
    }
  }

  private needsDecomposition(node: GoalNode): boolean {
    // Simple heuristic: decompose if goal is vague (> 10 words)
    const words = node.goal.split(/\s+/).length;
    return words > 10 && node.depth < 5;
  }

  private async generateSubgoals(goalText: string, context: GoalContext): Promise<string[]> {
    // This would use LLM in real implementation
    // For now, return generic subgoals
    const patterns = this.archive.getPatternsForGoal(goalText);

    if (patterns.length > 0) {
      // Use learned patterns
      return patterns[0].examples.slice(0, 3);
    }

    // Generic decomposition
    return [
      `Research context for: ${goalText.substring(0, 30)}`,
      `Plan approach for: ${goalText.substring(0, 30)}`,
      `Execute first step of: ${goalText.substring(0, 30)}`
    ];
  }

  private async executeGoal(goal: GoalNode, context: GoalContext): Promise<boolean> {
    // This would execute the actual goal in real implementation
    // For now, simulate with 70% success rate
    const success = Math.random() < 0.7;

    if (success) {
      goal.status = 'completed';
    } else {
      goal.status = 'failed';
      this.failedGoals++;

      // Check for rollback opportunity
      const previousSuccess = this.archive.findPreviousSuccess(goal.id);
      if (previousSuccess) {
        // Could rollback to previous approach
        console.log(`Found previous successful attempt: ${previousSuccess.id}`);
      }
    }

    return success;
  }
}

