/**
 * Complete Side-by-Side Comparison Test
 * Current Agent vs Goal Autonomy Agent
 * Model: liquid/lfm2-24b-a2b via LM Studio
 */

const LM_STUDIO_URL = 'http://localhost:1234/v1';
const MODEL = 'liquid/lfm2-24b-a2b';

// ============================================================================
// CURRENT AGENT (Reactive Only)
// ============================================================================

class CurrentAgent {
  async processRequest(request: string): Promise<string> {
    return `Processing: ${request}`;
  }

  async onHeartbeat(): Promise<string> {
    return "HEARTBEAT_OK";
  }
}

// ============================================================================
// GOAL AUTONOMY AGENT
// ============================================================================

interface GoalNode {
  id: string;
  goal: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  parent: string | null;
  children: string[];
  priority: number;
  usefulnessScore: number;
  depth: number;
  attempts: number;
  successRate: number;
}

class GoalTree {
  private nodes: Map<string, GoalNode> = new Map();
  private root: string | null = null;

  constructor(initialGoal?: string) {
    if (initialGoal) {
      const node = this.createNode(initialGoal, null);
      this.root = node.id;
    }
  }

  addNode(goal: string, parentId: string | null): GoalNode {
    return this.createNode(goal, parentId);
  }

  findMostUsefulSubgoal(): GoalNode | null {
    const pending = Array.from(this.nodes.values())
      .filter(n => n.status === 'pending');
    if (pending.length === 0) return null;
    pending.sort((a, b) => b.usefulnessScore - a.usefulnessScore);
    return pending[0];
  }

  async decomposeGoal(nodeId: string, subgoals: string[]): Promise<void> {
    for (const subgoal of subgoals) {
      this.createNode(subgoal, nodeId);
    }
  }

  updateUsefulness(nodeId: string, success: boolean): void {
    const node = this.nodes.get(nodeId);
    if (!node) return;
    node.successRate = (node.successRate + (success ? 1 : 0)) / 2;
    node.usefulnessScore = node.successRate * node.priority;
  }

  getNode(id: string): GoalNode | undefined {
    return this.nodes.get(id);
  }

  getRoot(): GoalNode | null {
    return this.root ? this.nodes.get(this.root) || null : null;
  }

  getAllNodes(): GoalNode[] {
    return Array.from(this.nodes.values());
  }

  private createNode(goal: string, parentId: string | null): GoalNode {
    const parent = parentId ? this.nodes.get(parentId) : null;
    const node: GoalNode = {
      id: `goal-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      goal,
      status: 'pending',
      parent: parentId,
      children: [],
      priority: 0.5,
      usefulnessScore: 0.5,
      depth: parent ? parent.depth + 1 : 0,
      attempts: 0,
      successRate: 0.5
    };
    this.nodes.set(node.id, node);
    if (parent) parent.children.push(node.id);
    return node;
  }
}

type DriveType = 'curiosity' | 'competence' | 'novelty';

class IntrinsicMotivationSystem {
  private drives: Map<DriveType, number> = new Map([
    ['curiosity', 0],
    ['competence', 0],
    ['novelty', 0]
  ]);

  updateDrives(type: 'surprise' | 'success', impact: number): void {
    if (type === 'surprise') {
      const current = this.drives.get('curiosity') || 0;
      this.drives.set('curiosity', Math.min(1, current + impact));
    } else {
      const current = this.drives.get('competence') || 0;
      this.drives.set('competence', Math.min(1, current + impact));
    }
  }

  getDriveLevels(): Map<DriveType, number> {
    return new Map(this.drives);
  }
}

class GoalArchive {
  private attempts: Array<{
    goalId: string;
    success: boolean;
    timestamp: number;
  }> = [];

  recordAttempt(goalId: string, success: boolean): void {
    this.attempts.push({ goalId, success, timestamp: Date.now() });
  }

  getStats(): { totalAttempts: number; successRate: number } {
    const total = this.attempts.length;
    const successes = this.attempts.filter(a => a.success).length;
    return {
      totalAttempts: total,
      successRate: total > 0 ? successes / total : 0
    };
  }

  findPreviousSuccess(goalId: string): boolean {
    return this.attempts.some(a => a.goalId === goalId && a.success);
  }
}

class GoalGenerationEngine {
  private goalTree: GoalTree;
  private motivation: IntrinsicMotivationSystem;
  private archive: GoalArchive;
  private completedGoals: number = 0;

  constructor() {
    this.goalTree = new GoalTree();
    this.motivation = new IntrinsicMotivationSystem();
    this.archive = new GoalArchive();
  }

  async generateAndPursueGoals(): Promise<{ generated: number; executed: number; completed: number }> {
    // Generate goal from motivation
    this.motivation.updateDrives('surprise', 0.8);
    const goal = this.goalTree.addNode('Improve system performance', null);

    // Decompose
    await this.goalTree.decomposeGoal(goal.id, [
      'Profile performance',
      'Find bottlenecks',
      'Optimize'
    ]);

    // Execute (simulate)
    const nextGoal = this.goalTree.findMostUsefulSubgoal();
    let completed = 0;
    if (nextGoal) {
      const success = Math.random() > 0.3;
      this.goalTree.updateUsefulness(nextGoal.id, success);
      this.archive.recordAttempt(nextGoal.id, success);
      if (success) {
        completed++;
        this.completedGoals++;
      }
    }

    return {
      generated: 4, // 1 root + 3 subgoals
      executed: 1,
      completed
    };
  }

  addExternalGoal(goalText: string): void {
    this.goalTree.addNode(goalText, null);
  }

  getStats(): { completedGoals: number } {
    return { completedGoals: this.completedGoals };
  }
}

