/**
 * Execute goal heartbeat (called periodically)
 */
async function executeGoalHeartbeat(): Promise<void> {
  if (!goalEngine) return;

  try {
    const startTime = Date.now();

    // 1. Sync with neuro-memory (load recent goal history)
    const neuroMemory = getNeuroMemoryBridge();
    if (neuroMemory) {
      try {
        const recentGoals = await neuroMemory.query({
          type: 'goal_completed',
          limit: 10
        });
        log.debug('Loaded recent goals from neuro-memory', { count: recentGoals.length });
      } catch (error) {
        log.warn('Failed to sync with neuro-memory', { error });
      }
    }

    // 2. Get predictive priority boosts
    const predictiveService = getPredictiveService();
    if (predictiveService) {
      try {
        const predictions = await predictiveService.check();
        if (predictions.length > 0) {
          log.debug('Predictive suggestions available', { count: predictions.length });
        }
      } catch (error) {
        log.warn('Failed to get predictive suggestions', { error });
      }
    }

    // 3. Generate and pursue goals
    const result = await goalEngine.generateAndPursueGoals();

    const elapsed = Date.now() - startTime;

    if (result.generated > 0 || result.completed > 0 || result.failed > 0) {
      log.info('🔄 Goal heartbeat', {
        generated: result.generated,
        completed: result.completed,
        failed: result.failed,
        active: result.active,
        elapsed: `${elapsed}ms`
      });

      // 4. Store completed goals in neuro-memory
      if (neuroMemory && result.completed > 0) {
        try {
          await neuroMemory.store({
            type: 'goal_heartbeat',
            data: result,
            timestamp: Date.now()
          });
        } catch (error) {
          log.warn('Failed to store goals in neuro-memory', { error });
        }
      }

      // 5. Emit to event mesh
      const eventMesh = getEventMesh();
      if (eventMesh) {
        await eventMesh.emit({
          type: 'goal_heartbeat',
          source: 'goal-autonomy',
          data: result
        });
      }
    }
  } catch (error) {
    log.error('Goal heartbeat failed', { error });
  }
}

