async generateAndPursueGoals(): Promise<{generated, completed, failed, active}> {
  // 1. Generate intrinsic goals (curiosity, competence)
  const intrinsicGoals = this.motivation.generateIntrinsicGoals();

  // 2. Get next pending goal (priority queue)
  const nextGoal = this.goalTree.getNextPendingGoal();

  // 3. Decompose if needed (2-5s LLM call)
  if (needsDecomposition) {
    subgoals = await this.decomposeGoal(goal, llmClient);
  }

  // 4. Execute goal (variable time)
  const success = await this.executeGoal(nextGoal);

  // 5. Archive and learn patterns
  this.archiveGoal(nextGoal, success);
}
```

