    ];

    // Don't await - fire and forget
    Promise.allSettled(writes);

    parentPort?.postMessage({
      result,
      timestamp: start,
      duration: Date.now() - start
    });
  } catch (error) {
    parentPort?.postMessage({
      error: error.message,
      timestamp: start
    });
  }
}

parentPort?.on('message', async (msg) => {
  if (msg.type === 'heartbeat') {
