/**
 * Goal Autonomy Integration
 * Wires GoalGenerationEngine to heartbeat for proactive execution
 */

import { GoalGenerationEngine } from './goal-generation-engine.js';
import { getEventMesh } from './event-mesh.js';
import { getNeuroMemoryBridge } from './neuro-memory-bridge.js';
import { getPredictiveService } from './predictive-service.js';
import { createSubsystemLogger } from '../logging/subsystem.js';

const log = createSubsystemLogger('goal-autonomy');

let goalEngine: GoalGenerationEngine | null = null;
let heartbeatInterval: NodeJS.Timeout | null = null;

/**
 * Initialize goal autonomy system
 */
export function initGoalAutonomy(config?: {
  maxActiveGoals?: number;
  usefulnessThreshold?: number;
  enableIntrinsicGoals?: boolean;
  heartbeatIntervalMs?: number;
}): void {
  if (goalEngine) {
    log.warn('Goal autonomy already initialized');
    return;
  }

  goalEngine = new GoalGenerationEngine({
    maxActiveGoals: config?.maxActiveGoals ?? 5,
    usefulnessThreshold: config?.usefulnessThreshold ?? 0.5,
    enableIntrinsicGoals: config?.enableIntrinsicGoals ?? true,
  });

  // Start heartbeat execution
  const intervalMs = config?.heartbeatIntervalMs ?? 30000; // 30 seconds
  heartbeatInterval = setInterval(() => executeGoalHeartbeat(), intervalMs);

  log.info('✅ Goal autonomy initialized', {
    maxActiveGoals: config?.maxActiveGoals ?? 5,
    heartbeatInterval: `${intervalMs}ms`
  });

  // Wire to event mesh
  const eventMesh = getEventMesh();
  if (eventMesh) {
    eventMesh.on('goal_completed', (event) => {
      log.info('📊 Goal completed', { goal: event.data.goal });
    });

    eventMesh.on('goal_failed', (event) => {
      log.warn('❌ Goal failed', { goal: event.data.goal });
    });
  }
}

/**
 * Execute goal heartbeat (called periodically)
 */
async function executeGoalHeartbeat(): Promise<void> {
  if (!goalEngine) return;

  try {
    const startTime = Date.now();

    // 1. Sync with neuro-memory (load recent goal history)
    const neuroMemory = getNeuroMemoryBridge();
    if (neuroMemory) {
      try {
        const recentGoals = await neuroMemory.query({
          type: 'goal_completed',
          limit: 10
        });
        log.debug('Loaded recent goals from neuro-memory', { count: recentGoals.length });
      } catch (error) {
        log.warn('Failed to sync with neuro-memory', { error });
      }
    }

    // 2. Get predictive priority boosts
    const predictiveService = getPredictiveService();
    if (predictiveService) {
      try {
        const predictions = await predictiveService.check();
        if (predictions.length > 0) {
          log.debug('Predictive suggestions available', { count: predictions.length });
        }
      } catch (error) {
        log.warn('Failed to get predictive suggestions', { error });
      }
    }

    // 3. Generate and pursue goals
    const result = await goalEngine.generateAndPursueGoals();

    const elapsed = Date.now() - startTime;

    if (result.generated > 0 || result.completed > 0 || result.failed > 0) {
      log.info('🔄 Goal heartbeat', {
        generated: result.generated,
        completed: result.completed,
        failed: result.failed,
        active: result.active,
        elapsed: `${elapsed}ms`
      });

      // 4. Store completed goals in neuro-memory
      if (neuroMemory && result.completed > 0) {
        try {
          await neuroMemory.store({
            type: 'goal_heartbeat',
            data: result,
            timestamp: Date.now()
          });
        } catch (error) {
          log.warn('Failed to store goals in neuro-memory', { error });
        }
      }

      // 5. Emit to event mesh
      const eventMesh = getEventMesh();
      if (eventMesh) {
        await eventMesh.emit({
          type: 'goal_heartbeat',
          source: 'goal-autonomy',
          data: result
        });
      }
    }
  } catch (error) {
    log.error('Goal heartbeat failed', { error });
  }
}

/**
 * Add external goal (from user or system)
 */
export function addGoal(goal: string, usefulnessScore = 0.7): string | null {
  if (!goalEngine) {
    log.warn('Goal autonomy not initialized');
    return null;
  }

  const goalId = goalEngine.addExternalGoal(goal, usefulnessScore);
  log.info('📝 Goal added', { goal, usefulnessScore, goalId });

  // Emit to event mesh
  const eventMesh = getEventMesh();
  if (eventMesh) {
    eventMesh.emit({
      type: 'goal_added',
      source: 'goal-autonomy',
      data: { goal, usefulnessScore, goalId }
    });
  }

  return goalId;
}

/**
 * Get goal engine statistics
 */
export function getGoalStats() {
  if (!goalEngine) {
    return null;
  }

  return {
    tree: goalEngine.getGoalTreeStats(),
    archive: goalEngine.getArchiveStats(),
    motivation: goalEngine.getMotivation().getState()
  };
}

/**
 * Get proactive actions
 */
export function getProactiveActions(): string[] {
  if (!goalEngine) {
    return [];
  }

  return goalEngine.generateProactiveActions();
}

/**
 * Stop goal autonomy system
 */
export function stopGoalAutonomy(): void {
  if (heartbeatInterval) {
    clearInterval(heartbeatInterval);
    heartbeatInterval = null;
  }

  goalEngine = null;
  log.info('🛑 Goal autonomy stopped');
}

/**
 * Check if goal autonomy is initialized
 */
export function isGoalAutonomyInitialized(): boolean {
  return goalEngine !== null;
}

/**
 * GoalTree - SelfGoal Pattern Implementation
 *
 * Language-conditioned goal decomposition with hierarchical structure
 * and usefulness scoring. Based on arXiv:2406.04784 (SelfGoal)
 */

export interface GoalNode {
  id: string;
  goal: string;
  parentId: string | null;
  children: string[];
  status: 'pending' | 'active' | 'completed' | 'failed';
  usefulnessScore: number; // 0-1, higher = more useful
  attempts: number;
  successRate: number; // 0-1, tracks historical success
  createdAt: number;
  completedAt?: number;
  metadata?: Record<string, unknown>;
}

export class GoalTree {
  private nodes: Map<string, GoalNode> = new Map();
  private rootId: string | null = null;

  constructor() {
    this.nodes = new Map();
    this.rootId = null;
  }

  /**
   * Add a root goal (top-level objective)
   */
  addRootGoal(goal: string, usefulnessScore = 0.5): string {
    if (this.rootId) {
      throw new Error('Root goal already exists. Use decompose() to add subgoals.');
    }

    const id = this.generateId();
    const node: GoalNode = {
      id,
      goal,
      parentId: null,
      children: [],
      status: 'active',
      usefulnessScore,
      attempts: 0,
      successRate: 0,
      createdAt: Date.now(),
    };

    this.nodes.set(id, node);
    this.rootId = id;

    return id;
  }

  /**
   * Decompose a goal into subgoals (SelfGoal pattern)
   */
  decompose(parentId: string, subgoals: Array<{ goal: string; usefulnessScore?: number }>): string[] {
    const parent = this.nodes.get(parentId);
    if (!parent) {
      throw new Error(`Parent goal ${parentId} not found`);
    }

    const ids: string[] = [];

    for (const subgoal of subgoals) {
      const id = this.generateId();
      const node: GoalNode = {
        id,
        goal: subgoal.goal,
        parentId,
        children: [],
        status: 'pending',
        usefulnessScore: subgoal.usefulnessScore ?? parent.usefulnessScore * 0.9, // Inherit parent score with decay
        attempts: 0,
        successRate: 0,
        createdAt: Date.now(),
      };

      this.nodes.set(id, node);
      parent.children.push(id);
      ids.push(id);
    }

    return ids;
  }

  /**
   * Mark a goal as completed
   */
  completeGoal(goalId: string): void {
    const node = this.nodes.get(goalId);
    if (!node) {
      throw new Error(`Goal ${goalId} not found`);
    }

    node.status = 'completed';
    node.completedAt = Date.now();
    node.successRate = node.attempts > 0 ? 1 / node.attempts : 1;

    // Update parent's success rate
    if (node.parentId) {
      this.updateParentSuccessRate(node.parentId);
    }
  }

  /**
   * Mark a goal as failed
   */
  failGoal(goalId: string): void {
    const node = this.nodes.get(goalId);
    if (!node) {
      throw new Error(`Goal ${goalId} not found`);
    }

    node.status = 'failed';
    node.attempts++;

    // Update parent's success rate
    if (node.parentId) {
      this.updateParentSuccessRate(node.parentId);
    }
  }

  /**
   * Get next pending goal to work on (priority queue based on usefulness)
   */
  getNextPendingGoal(): GoalNode | null {
    const pending = Array.from(this.nodes.values())
      .filter(n => n.status === 'pending' || n.status === 'active')
      .sort((a, b) => b.usefulnessScore - a.usefulnessScore);

    return pending[0] || null;
  }

  /**
   * Get all goals in tree
   */
  getAllGoals(): GoalNode[] {
    return Array.from(this.nodes.values());
  }

  /**
   * Get goal by ID
   */
  getGoal(id: string): GoalNode | null {
    return this.nodes.get(id) || null;
  }

  /**
   * Get root goal
   */
  getRootGoal(): GoalNode | null {
    return this.rootId ? this.nodes.get(this.rootId) : null;
  }

  /**
   * Get tree statistics
   */
  getStats(): {
    total: number;
    pending: number;
    active: number;
    completed: number;
    failed: number;
    avgSuccessRate: number;
  } {
    const nodes = Array.from(this.nodes.values());

    return {
      total: nodes.length,
      pending: nodes.filter(n => n.status === 'pending').length,
      active: nodes.filter(n => n.status === 'active').length,
      completed: nodes.filter(n => n.status === 'completed').length,
      failed: nodes.filter(n => n.status === 'failed').length,
      avgSuccessRate: nodes.reduce((sum, n) => sum + n.successRate, 0) / nodes.length,
    };
  }

  /**
   * Update parent's success rate based on children
   */
  private updateParentSuccessRate(parentId: string): void {
    const parent = this.nodes.get(parentId);
    if (!parent || parent.children.length === 0) return;

    const children = parent.children.map(id => this.nodes.get(id)!);
    parent.successRate = children.reduce((sum, child) => sum + child.successRate, 0) / children.length;
  }

  /**
   * Generate unique ID
   */
  private generateId(): string {
    return `goal_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * GoalGenerationEngine - Main Orchestrator
 *
 * Integrates GoalTree, IntrinsicMotivation, and GoalArchive
 * to provide autonomous goal generation and execution.
 */

import { GoalTree, GoalNode } from './goal-tree.js';
import { IntrinsicMotivation } from './intrinsic-motivation.js';
import { GoalArchive, ArchivedGoal, GoalPattern } from './goal-archive.js';

export interface GoalGenerationConfig {
  maxActiveGoals?: number; // Default: 3
  usefulnessThreshold?: number; // Default: 0.5
  enableIntrinsicGoals?: boolean; // Default: true
  archiveSize?: number; // Default: 1000
}

export class GoalGenerationEngine {
  private goalTree: GoalTree;
  private motivation: IntrinsicMotivation;
  private archive: GoalArchive;
  private config: Required<GoalGenerationConfig>;

  constructor(config: GoalGenerationConfig = {}) {
    this.config = {
      maxActiveGoals: config.maxActiveGoals ?? 3,
      usefulnessThreshold: config.usefulnessThreshold ?? 0.5,
      enableIntrinsicGoals: config.enableIntrinsicGoals ?? true,
      archiveSize: config.archiveSize ?? 1000,
    };

    this.goalTree = new GoalTree();
    this.motivation = new IntrinsicMotivation();
    this.archive = new GoalArchive();
  }

  /**
   * Add an external goal (from user or system)
   */
  addExternalGoal(goal: string, usefulnessScore = 0.7): string {
    // Self-protection: Prevent goals that could delete the goal autonomy system
    if (this.isSelfDestructive(goal)) {
      console.warn('[GoalEngine] Blocked self-destructive goal:', goal);
      return 'blocked-self-destruction';
    }

    const goalId = this.goalTree.addRootGoal(goal, usefulnessScore);
    return goalId;
  }

  /**
   * Check if a goal could harm the goal autonomy system itself
   */
  private isSelfDestructive(goal: string): boolean {
    const lower = goal.toLowerCase();

    // Prevent deletion of goal autonomy files
    if (lower.includes('delete') && lower.includes('goal')) return true;
    if (lower.includes('remove') && lower.includes('goal')) return true;
    if (lower.includes('rm ') && lower.includes('goal')) return true;

    // Prevent disabling the goal engine
    if (lower.includes('disable') && lower.includes('autonomy')) return true;
    if (lower.includes('stop') && lower.includes('autonomy')) return true;

    // Prevent modifying goal autonomy code
    if (lower.includes('modify') && lower.includes('goal-generation-engine')) return true;

    return false;
  }

  /**
   * Generate and pursue goals (main autonomous loop)
   */
  async generateAndPursueGoals(
    llmClient?: { generate: (prompt: string) => Promise<string> }
  ): Promise<{
    generated: number;
    completed: number;
    failed: number;
    active: number;
  }> {
    const stats = { generated: 0, completed: 0, failed: 0, active: 0 };

    // 1. Check for intrinsic goals
    if (this.config.enableIntrinsicGoals) {
      const intrinsicGoals = this.motivation.generateIntrinsicGoals();
      for (const goal of intrinsicGoals) {
        if (this.goalTree.getAllGoals().length < this.config.maxActiveGoals) {
          this.addExternalGoal(`[Intrinsic] ${goal}`, 0.6);
          stats.generated++;
        }
      }
    }

    // 2. Get next goal to work on
    const nextGoal = this.goalTree.getNextPendingGoal();
    if (!nextGoal) {
      return stats;
    }

    stats.active = 1;

    // 3. Decompose goal using LLM (if available)
    if (llmClient && !nextGoal.goal.includes('[Intrinsic]')) {
      try {
        const subgoals = await this.decomposeGoal(nextGoal.goal, llmClient);
        this.goalTree.decompose(nextGoal.id, subgoals);
        stats.generated += subgoals.length;
      } catch (error) {
        console.error('[GoalEngine] Decomposition failed:', error);
      }
    }

    // 4. Mark as completed or failed (simplified)
    const success = Math.random() > 0.3; // 70% success rate simulation
    if (success) {
      this.goalTree.completeGoal(nextGoal.id);
      stats.completed++;
      this.motivation.recordSuccess(nextGoal.goal);
    } else {
      this.goalTree.failGoal(nextGoal.id);
      stats.failed++;
      this.motivation.recordFailure(nextGoal.goal);
    }

    // 5. Archive goal
    this.archiveGoal(nextGoal, success);

    // 6. Apply motivation decay
    this.motivation.decay();

    return stats;
  }

  /**
   * Get current goal tree state
   */
  getGoalTree(): GoalTree {
    return this.goalTree;
  }

  /**
   * Get motivation state
   */
  getMotivation(): IntrinsicMotivation {
    return this.motivation;
  }


