/**
 * Shared HTTP Client with Connection Pooling and Circuit Breaker
 * 
 * Features:
 * - Connection pooling (keep-alive)
 * - Circuit breaker for resilience
 * - Automatic retry with backoff
 * - Request timeout handling
 * - Metrics collection
 */

import http from "node:http";
import https from "node:https";
import { createSubsystemLogger } from "../logging/subsystem.js";

const log = createSubsystemLogger("http-client");

// Circuit breaker states
type CircuitState = "closed" | "open" | "half-open";

export interface CircuitBreakerConfig {
  /** Failure threshold before opening circuit - default: 5 */
  threshold?: number;
  /** Time to wait before trying half-open (ms) - default: 60000 */
  timeout?: number;
  /** Success threshold to close circuit - default: 3 */
  successThreshold?: number;
}

export interface HttpClientConfig {
  /** Connection pool max sockets per host - default: 50 */
  maxSockets?: number;
  /** Connection pool max free sockets - default: 10 */
  maxFreeSockets?: number;
  /** Default request timeout (ms) - default: 30000 */
  timeout?: number;
  /** Circuit breaker config */
  circuitBreaker?: CircuitBreakerConfig;
  /** Enable request metrics */
  enableMetrics?: boolean;
}

interface RequestMetrics {
  total: number;
  successful: number;
  failed: number;
  avgDuration: number;
  lastError?: string;
  lastErrorTime?: number;
}

/**
 * Circuit Breaker Implementation
 */
class CircuitBreaker {
  private state: CircuitState = "closed";
  private failures = 0;
  private successes = 0;
  private lastFailureTime = 0;
  private readonly threshold: number;
  private readonly timeout: number;
  private readonly successThreshold: number;

  constructor(config: CircuitBreakerConfig = {}) {
    this.threshold = config.threshold ?? 5;
    this.timeout = config.timeout ?? 60000;
    this.successThreshold = config.successThreshold ?? 3;
  }

  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === "open") {
      const elapsed = Date.now() - this.lastFailureTime;
      if (elapsed < this.timeout) {
        throw new Error("Circuit breaker is OPEN - too many failures");
      }
      this.state = "half-open";
      log.debug("Circuit breaker moved to HALF-OPEN");
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  private onSuccess(): void {
    if (this.state === "half-open") {
      this.successes++;
      if (this.successes >= this.successThreshold) {
        this.state = "closed";
        this.failures = 0;
        this.successes = 0;
        log.info("Circuit breaker CLOSED - recovered");
      }
    } else {
      this.failures = 0;
    }
  }

  private onFailure(): void {
    this.failures++;
    this.lastFailureTime = Date.now();

    if (this.failures >= this.threshold) {
      this.state = "open";
      log.warn(`Circuit breaker OPENED after ${this.failures} failures`);
    }
  }

  getState(): CircuitState {
    return this.state;
  }

  getFailures(): number {
    return this.failures;
  }
}

/**
 * Shared HTTP Client with Connection Pooling
 */
export class HttpClient {
  private readonly httpAgent: http.Agent;
  private readonly httpsAgent: https.Agent;
  private readonly circuitBreaker: CircuitBreaker;
  private readonly defaultTimeout: number;
  private readonly enableMetrics: boolean;
  private readonly metrics = new Map<string, RequestMetrics>();

  constructor(config: HttpClientConfig = {}) {
    const maxSockets = config.maxSockets ?? 50;
    const maxFreeSockets = config.maxFreeSockets ?? 10;

    // Create connection pooling agents
    this.httpAgent = new http.Agent({
      keepAlive: true,
      maxSockets,
      maxFreeSockets,
      timeout: 60000, // Socket timeout
    });

    this.httpsAgent = new https.Agent({
      keepAlive: true,
      maxSockets,
      maxFreeSockets,
      timeout: 60000,
    });

    this.circuitBreaker = new CircuitBreaker(config.circuitBreaker);
    this.defaultTimeout = config.timeout ?? 30000;
    this.enableMetrics = config.enableMetrics ?? false;

    log.debug(`HTTP client initialized (maxSockets=${maxSockets}, maxFreeSockets=${maxFreeSockets})`);
  }

  /**
   * Fetch with connection pooling and circuit breaker
   */
  async fetch(
    url: string | URL,
    options?: RequestInit & { timeout?: number }
  ): Promise<Response> {
    const urlString = url.toString();
    const urlObj = new URL(urlString);
    const isHttps = urlObj.protocol === "https:";
    const startTime = Date.now();
    const timeout = options?.timeout ?? this.defaultTimeout;

    // Use circuit breaker
    return this.circuitBreaker.execute(async () => {
      try {
        // Create abort controller for timeout
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeout);

        const fetchOptions: RequestInit = {
          ...options,
          signal: controller.signal,
          // @ts-expect-error Node.js specific agent option
          agent: isHttps ? this.httpsAgent : this.httpAgent,
        };

        const response = await fetch(url, fetchOptions);
        clearTimeout(timeoutId);

        if (this.enableMetrics) {
          this.recordMetrics(urlString, Date.now() - startTime, true);
        }

        return response;
      } catch (error) {
        if (this.enableMetrics) {
          this.recordMetrics(urlString, Date.now() - startTime, false, String(error));
        }
        throw error;
      }
    });
  }

  /**
   * JSON fetch helper
   */
  async fetchJson<T = unknown>(
    url: string | URL,
    options?: RequestInit & { timeout?: number }
  ): Promise<T> {
    const response = await this.fetch(url, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options?.headers,
      },
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json() as Promise<T>;
  }

  /**
   * POST JSON helper
   */
  async postJson<T = unknown>(
    url: string | URL,
    data: unknown,
    options?: RequestInit & { timeout?: number }
  ): Promise<T> {
    return this.fetchJson<T>(url, {
      ...options,
      method: "POST",
      body: JSON.stringify(data),
    });
  }

  /**
   * Get circuit breaker state
   */
  getCircuitState(): CircuitState {
    return this.circuitBreaker.getState();
  }

  /**
   * Get metrics for a URL pattern
   */
  getMetrics(urlPattern?: string): Map<string, RequestMetrics> {
    if (urlPattern) {
      const result = new Map<string, RequestMetrics>();
      const metrics = this.metrics.get(urlPattern);
      if (metrics) {
        result.set(urlPattern, metrics);
      }
      return result;
    }
    return new Map(this.metrics);
  }

  /**
   * Record request metrics
   */
  private recordMetrics(
    url: string,
    duration: number,
    success: boolean,
    error?: string
  ): void {
    const key = this.normalizeUrl(url);
    let metrics = this.metrics.get(key);

    if (!metrics) {
      metrics = { total: 0, successful: 0, failed: 0, avgDuration: 0 };
      this.metrics.set(key, metrics);
    }

    metrics.total++;
    if (success) {
      metrics.successful++;
    } else {
      metrics.failed++;
      metrics.lastError = error;
      metrics.lastErrorTime = Date.now();
    }

    // Calculate rolling average
    const totalDuration = metrics.avgDuration * (metrics.total - 1) + duration;
    metrics.avgDuration = totalDuration / metrics.total;
  }

  /**
   * Normalize URL for metrics (remove query params, IDs)
   */
  private normalizeUrl(url: string): string {
    try {
      const urlObj = new URL(url);
      // Remove query params
      return `${urlObj.origin}${urlObj.pathname}`;
    } catch {
      return url;
    }
  }

  /**
   * Cleanup agents on shutdown
   */
  destroy(): void {
    this.httpAgent.destroy();
    this.httpsAgent.destroy();
    log.debug("HTTP client destroyed");
  }
}

// Singleton instance
let defaultClient: HttpClient | null = null;

/**
 * Get or create default HTTP client
 */
export function getHttpClient(config?: HttpClientConfig): HttpClient {
  if (!defaultClient) {
    defaultClient = new HttpClient(config);
  }
  return defaultClient;
}

/**
 * Reset default client (for testing)
 */
export function resetHttpClient(): void {
  if (defaultClient) {
    defaultClient.destroy();
    defaultClient = null;
  }
}

/**
 * LRU Cache Implementation
 * 
 * Features:
 * - O(1) get/set operations
 * - TTL support (time-to-live)
 * - Max size with automatic eviction
 * - Memory-efficient
 * - Stats tracking
 */

import { createSubsystemLogger } from "../logging/subsystem.js";

const log = createSubsystemLogger("lru-cache");

export interface LRUCacheConfig {
  /** Maximum number of items - default: 1000 */
  maxSize?: number;
  /** Time-to-live in milliseconds - default: 3600000 (1 hour) */
  ttl?: number;
  /** Enable stats tracking */
  enableStats?: boolean;
}

interface CacheEntry<V> {
  value: V;
  timestamp: number;
  ttl: number;
}

interface CacheStats {
  hits: number;
  misses: number;
  evictions: number;
  size: number;
  maxSize: number;
}

/**
 * Generic LRU Cache with TTL support
 */
export class LRUCache<K = string, V = unknown> {
  private readonly cache = new Map<K, CacheEntry<V>>();
  private readonly maxSize: number;
  private readonly defaultTtl: number;
  private readonly enableStats: boolean;
  private stats: CacheStats;

  constructor(config: LRUCacheConfig = {}) {
    this.maxSize = config.maxSize ?? 1000;
    this.defaultTtl = config.ttl ?? 3600000; // 1 hour
    this.enableStats = config.enableStats ?? false;
    this.stats = {
      hits: 0,
      misses: 0,
      evictions: 0,
      size: 0,
      maxSize: this.maxSize,
    };
  }

  /**
   * Get value from cache
   */
  get(key: K): V | undefined {
    const entry = this.cache.get(key);

    if (!entry) {
      if (this.enableStats) this.stats.misses++;
      return undefined;
    }

    // Check TTL
    if (this.isExpired(entry)) {
      this.cache.delete(key);
      if (this.enableStats) {
        this.stats.misses++;
        this.stats.evictions++;
        this.stats.size = this.cache.size;
      }
      return undefined;
    }

    // Move to end (most recently used)
    this.cache.delete(key);
    this.cache.set(key, entry);

    if (this.enableStats) this.stats.hits++;
    return entry.value;
  }

  /**
   * Set value in cache
   */
  set(key: K, value: V, ttl?: number): void {
    // Remove if exists (to update position)
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }

    // Evict oldest if at capacity
    else if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) {
        this.cache.delete(firstKey);
        if (this.enableStats) {
          this.stats.evictions++;
        }
      }
    }

    // Add new entry
    this.cache.set(key, {
      value,
      timestamp: Date.now(),
      ttl: ttl ?? this.defaultTtl,
    });

    if (this.enableStats) {
      this.stats.size = this.cache.size;
    }
  }

  /**
   * Check if key exists (without updating access order)
   */
  has(key: K): boolean {
    const entry = this.cache.get(key);
    if (!entry) return false;

    if (this.isExpired(entry)) {
      this.cache.delete(key);
      if (this.enableStats) {
        this.stats.evictions++;
        this.stats.size = this.cache.size;
      }
      return false;
    }

    return true;
  }

  /**
   * Delete key from cache
   */
  delete(key: K): boolean {
    const deleted = this.cache.delete(key);
    if (deleted && this.enableStats) {
      this.stats.size = this.cache.size;
    }
    return deleted;
  }

  /**
   * Clear entire cache
   */
  clear(): void {
    const size = this.cache.size;
    this.cache.clear();
    if (this.enableStats) {
      this.stats.evictions += size;
      this.stats.size = 0;
    }
  }

  /**
   * Get current size
   */
  get size(): number {
    return this.cache.size;
  }

  /**
   * Get cache statistics
   */
  getStats(): CacheStats {
    return { ...this.stats };
  }

  /**
   * Get hit rate (0-1)
   */
  getHitRate(): number {
    if (!this.enableStats) return 0;
    const total = this.stats.hits + this.stats.misses;
    return total === 0 ? 0 : this.stats.hits / total;
  }

  /**
   * Cleanup expired entries
   */
  cleanup(): number {
    let cleaned = 0;
    for (const [key, entry] of this.cache.entries()) {
      if (this.isExpired(entry)) {
        this.cache.delete(key);
        cleaned++;
      }
    }
    if (cleaned > 0 && this.enableStats) {
      this.stats.evictions += cleaned;
      this.stats.size = this.cache.size;
      log.debug(`Cleaned ${cleaned} expired entries`);
    }
    return cleaned;
  }

  /**
   * Check if entry is expired
   */
  private isExpired(entry: CacheEntry<V>): boolean {
    return Date.now() - entry.timestamp > entry.ttl;
  }
}

/**
 * Embedding Cache - Specialized for embedding vectors
 */
export class EmbeddingCache {
  private readonly cache: LRUCache<string, number[]>;
  private readonly textToKey: (text: string) => string;

  constructor(config: LRUCacheConfig = {}) {
    this.cache = new LRUCache<string, number[]>({
      maxSize: config.maxSize ?? 1000,
      ttl: config.ttl ?? 86400000, // 24 hours for embeddings
      enableStats: config.enableStats ?? true,
    });

    // Simple hash function for text
    this.textToKey = (text: string): string => {
      let hash = 0;
      for (let i = 0; i < text.length; i++) {
        const char = text.charCodeAt(i);
        hash = (hash << 5) - hash + char;
        hash = hash & hash; // Convert to 32-bit integer
      }
      return `emb_${hash}_${text.length}`;
    };
  }

  /**
   * Get embedding from cache
   */
  get(text: string): number[] | undefined {
    return this.cache.get(this.textToKey(text));
  }

  /**
   * Set embedding in cache
   */
  set(text: string, embedding: number[]): void {
    this.cache.set(this.textToKey(text), embedding);
  }

  /**
   * Get or compute embedding
   */
  async getOrCompute(
    text: string,
    compute: () => Promise<number[]>
  ): Promise<number[]> {
    const cached = this.get(text);
    if (cached) {
      return cached;
    }

    const embedding = await compute();
    this.set(text, embedding);
    return embedding;
  }

  /**
   * Batch get or compute embeddings
   */
  async batchGetOrCompute(
    texts: string[],
    compute: (texts: string[]) => Promise<number[][]>
  ): Promise<number[][]> {
    const results: number[][] = new Array(texts.length);
    const toCompute: { index: number; text: string }[] = [];

    // Check cache for each text
    for (let i = 0; i < texts.length; i++) {
      const cached = this.get(texts[i]);
      if (cached) {
        results[i] = cached;
      } else {
        toCompute.push({ index: i, text: texts[i] });
      }
    }

    // Compute missing embeddings
    if (toCompute.length > 0) {
      const textsToCompute = toCompute.map((t) => t.text);
      const computed = await compute(textsToCompute);

      // Store in cache and fill results
      for (let i = 0; i < toCompute.length; i++) {
        const { index } = toCompute[i];
        results[index] = computed[i];
        this.set(toCompute[i].text, computed[i]);
      }
    }

    return results;
  }

  /**
   * Get cache statistics
   */
  getStats(): { hitRate: number; size: number; maxSize: number } {
    const stats = this.cache.getStats();
    return {
      hitRate: this.cache.getHitRate(),
      size: stats.size,
      maxSize: stats.maxSize,
    };
  }

  /**
   * Clear cache
   */
  clear(): void {
    this.cache.clear();
  }

  /**
   * Cleanup expired entries
   */
  cleanup(): number {
    return this.cache.cleanup();
  }
}

// Singleton embedding cache
let embeddingCache: EmbeddingCache | null = null;

/**
 * Get or create embedding cache
 */
export function getEmbeddingCache(config?: LRUCacheConfig): EmbeddingCache {
  if (!embeddingCache) {
    embeddingCache = new EmbeddingCache(config);
  }
  return embeddingCache;
}

/**
 * Reset embedding cache (for testing)
 */
export function resetEmbeddingCache(): void {
  embeddingCache = null;
}

