/**
 * HTTP Client Tests
 */

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { HttpClient, getHttpClient, resetHttpClient } from "./http-client.js";

describe("HttpClient", () => {
  let client: HttpClient;

  beforeEach(() => {
    resetHttpClient();
    client = new HttpClient({
        maxSockets: 10,
        maxFreeSockets: 5,
        timeout: 5000,
        circuitBreaker: {
          threshold: 3,
          timeout: 1000,
          successThreshold: 2,
        },
        enableMetrics: true,
      });
  });

  afterEach(() => {
    client.destroy();
  });

  describe("Connection Pooling", () => {
    it("should reuse connections with keep-alive", async () => {
      const mockServer = "https://httpbin.org";

      // Make multiple requests to same host
      const results = await Promise.all([
        client.fetch(`${mockServer}/get?id=1`),
        client.fetch(`${mockServer}/get?id=2`),
        client.fetch(`${mockServer}/get?id=3`),
      ]);

      expect(results).toHaveLength(3);
      results.forEach(r => expect(r.ok).toBe(true));
    });

    it("should handle concurrent requests efficiently", async () => {
      const urls = Array.from({ length: 10 }, (_, i) => 
        `https://httpbin.org/get?n=${i}`
      );

      const start = Date.now();
      const results = await Promise.all(urls.map(url => client.fetch(url)));
      const duration = Date.now() - start;

      expect(results).toHaveLength(10);
      // Should complete in <5 seconds with connection pooling
      expect(duration).toBeLessThan(5000);
    });
  });

  describe("Circuit Breaker", () => {
    it("should start in CLOSED state", () => {
      expect(client.getCircuitState()).toBe("closed");
    });

    it("should OPEN after threshold failures", async () => {
      // Force failures with invalid URLs
      const failingUrl = "http://localhost:99999/fail";

      for (let i = 0; i < 3; i++) {
        try {
          await client.fetch(failingUrl);
        } catch {
          // Expected to fail
        }
      }

      expect(client.getCircuitState()).toBe("open");
    });

    it("should reject requests when OPEN", async () => {
      // Force circuit to open
      const failingUrl = "http://localhost:99999/fail";
      for (let i = 0; i < 3; i++) {
        try {
          await client.fetch(failingUrl);
        } catch {}
      }

      expect(client.getCircuitState()).toBe("open");

      // Next request should fail immediately
      await expect(client.fetch("https://httpbin.org/get")).rejects.toThrow(
        "Circuit breaker is OPEN"
      );
    });

    it("should transition to HALF-OPEN after timeout", async () => {
      // Force circuit to open
      const failingUrl = "http://localhost:99999/fail";
      for (let i = 0; i < 3; i++) {
        try {
          await client.fetch(failingUrl);
        } catch {}
      }

      expect(client.getCircuitState()).toBe("open");

      // Wait for timeout
      await new Promise(resolve => setTimeout(resolve, 1100));

      // Next request should try (half-open)
      try {
        await client.fetch("https://httpbin.org/get");
      } catch {
        // May still fail, but circuit should try
      }

      // Circuit should be half-open or closed now
      const state = client.getCircuitState();
      expect(["half-open", "closed"]).toContain(state);
    });

    it("should CLOSE after success threshold in HALF-OPEN", async () => {
      // Force circuit to open
      const failingUrl = "http://localhost:99999/fail";
      for (let i = 0; i < 3; i++) {
        try {
          await client.fetch(failingUrl);
        } catch {}
      }

      // Wait for timeout
      await new Promise(resolve => setTimeout(resolve, 1100));

      // Make successful requests to close circuit
      for (let i = 0; i < 2; i++) {
        await client.fetch("https://httpbin.org/get");
      }

      expect(client.getCircuitState()).toBe("closed");
    });
  });

  describe("Request Timeout", () => {
    it("should timeout slow requests", async () => {
      const slowUrl = "https://httpbin.org/delay/10"; // 10 second delay

      await expect(
        client.fetch(slowUrl, { timeout: 100 })
      ).rejects.toThrow();
    }, 10000);
  });

  describe("JSON Helpers", () => {
    it("should fetch and parse JSON", async () => {
      const data = await client.fetchJson<{ url: string }>(
        "https://httpbin.org/get"
      );

      expect(data).toBeDefined();
      expect(data.url).toContain("httpbin.org");
    });

    it("should POST JSON data", async () => {
      const payload = { message: "test", count: 42 };
      const response = await client.postJson<{ json: typeof payload }>(
        "https://httpbin.org/post",
        payload
      );

      expect(response.json).toEqual(payload);
    });

    it("should throw on non-OK responses", async () => {
      await expect(
        client.fetchJson("https://httpbin.org/status/404")
      ).rejects.toThrow("HTTP 404");
    });
  });

  describe("Metrics", () => {
    it("should track successful requests", async () => {
      await client.fetch("https://httpbin.org/get");
      await client.fetch("https://httpbin.org/get");

      const metrics = client.getMetrics();
      const urlMetrics = metrics.get("https://httpbin.org/get");

      expect(urlMetrics).toBeDefined();
      expect(urlMetrics?.total).toBe(2);
      expect(urlMetrics?.successful).toBe(2);
      expect(urlMetrics?.failed).toBe(0);
      expect(urlMetrics?.avgDuration).toBeGreaterThan(0);
    });

    it("should track failed requests", async () => {
      try {
        await client.fetch("http://localhost:99999/fail");
      } catch {}

      const metrics = client.getMetrics();
      const urlMetrics = metrics.get("http://localhost:99999/fail");

      expect(urlMetrics?.failed).toBe(1);
      expect(urlMetrics?.lastError).toBeDefined();
      expect(urlMetrics?.lastErrorTime).toBeGreaterThan(0);
    });

    it("should normalize URLs for metrics", async () => {
      await client.fetch("https://httpbin.org/get?param1=value1");
      await client.fetch("https://httpbin.org/get?param2=value2");

      const metrics = client.getMetrics();

      // Both requests should be grouped under same normalized URL
      expect(metrics.size).toBe(1);
      const urlMetrics = metrics.get("https://httpbin.org/get");
      expect(urlMetrics?.total).toBe(2);
    });
  });

  describe("Singleton", () => {
    it("should return same instance", () => {
      const instance1 = getHttpClient();
      const instance2 = getHttpClient();

      expect(instance1).toBe(instance2);
    });

    it("should reset singleton", () => {
      const instance1 = getHttpClient();
      resetHttpClient();
      const instance2 = getHttpClient();

      expect(instance1).not.toBe(instance2);
    });
  });
});

/**
 * LRU Cache Tests
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import { LRUCache, EmbeddingCache, getEmbeddingCache, resetEmbeddingCache } from "./lru-cache.js";

describe("LRUCache", () => {
  let cache: LRUCache<string, number>;

  beforeEach(() => {
    cache = new LRUCache<string, number>({
      maxSize: 3,
      ttl: 1000, // 1 second for testing
      enableStats: true,
    });
  });

  describe("Basic Operations", () => {
    it("should set and get values", () => {
      cache.set("a", 1);
      expect(cache.get("a")).toBe(1);
    });

    it("should return undefined for missing keys", () => {
      expect(cache.get("missing")).toBeUndefined();
    });

    it("should overwrite existing values", () => {
      cache.set("a", 1);
      cache.set("a", 2);
      expect(cache.get("a")).toBe(2);
    });

    it("should check if key exists", () => {
      cache.set("a", 1);
      expect(cache.has("a")).toBe(true);
      expect(cache.has("b")).toBe(false);
    });

    it("should delete keys", () => {
      cache.set("a", 1);
      expect(cache.delete("a")).toBe(true);
      expect(cache.get("a")).toBeUndefined();
      expect(cache.delete("a")).toBe(false);
    });

    it("should clear all keys", () => {
      cache.set("a", 1);
      cache.set("b", 2);
      cache.clear();
      expect(cache.size).toBe(0);
    });
  });

  describe("LRU Eviction", () => {
    it("should evict oldest entry when full", () => {
      cache.set("a", 1);
      cache.set("b", 2);
      cache.set("c", 3);
      cache.set("d", 4); // Should evict "a"

      expect(cache.get("a")).toBeUndefined();
      expect(cache.get("b")).toBe(2);
      expect(cache.get("c")).toBe(3);
      expect(cache.get("d")).toBe(4);
    });

    it("should update position on access", () => {
      cache.set("a", 1);
      cache.set("b", 2);
      cache.set("c", 3);

      // Access "a" to make it most recently used
      cache.get("a");

      // Add new item - should evict "b" instead of "a"
      cache.set("d", 4);

      expect(cache.get("a")).toBe(1); // Still there
      expect(cache.get("b")).toBeUndefined(); // Evicted
    });

    it("should update position on set", () => {
      cache.set("a", 1);
      cache.set("b", 2);
      cache.set("c", 3);

      // Update "a" to make it most recently used
      cache.set("a", 10);

      // Add new item - should evict "b" instead of "a"
      cache.set("d", 4);

      expect(cache.get("a")).toBe(10); // Updated and still there
      expect(cache.get("b")).toBeUndefined(); // Evicted
    });

    it("should respect max size", () => {
      for (let i = 0; i < 10; i++) {
        cache.set(`key${i}`, i);
      }

      // Should only have last 3 entries
      expect(cache.size).toBe(3);
    });
  });

  describe("TTL (Time To Live)", () => {
    it("should expire entries after TTL", async () => {
      cache.set("a", 1, 100); // 100ms TTL

      expect(cache.get("a")).toBe(1);

      await new Promise(resolve => setTimeout(resolve, 150));

      expect(cache.get("a")).toBeUndefined();
    });

    it("should use default TTL", async () => {
      cache.set("a", 1); // Uses default 1000ms TTL

      expect(cache.get("a")).toBe(1);

      await new Promise(resolve => setTimeout(resolve, 1100));

      expect(cache.get("a")).toBeUndefined();
    });

    it("should cleanup expired entries", async () => {
      cache.set("a", 1, 100);
      cache.set("b", 2, 100);
      cache.set("c", 3, 1000); // Won't expire

      await new Promise(resolve => setTimeout(resolve, 150));

      const cleaned = cache.cleanup();

      expect(cleaned).toBe(2);
      expect(cache.size).toBe(1);
      expect(cache.get("c")).toBe(3);
    });

    it("should treat expired entries as missing in has()", async () => {
      cache.set("a", 1, 100);

      await new Promise(resolve => setTimeout(resolve, 150));

      expect(cache.has("a")).toBe(false);
    });
  });

  describe("Statistics", () => {
    it("should track hits and misses", () => {
      cache.set("a", 1);

      cache.get("a"); // Hit
      cache.get("a"); // Hit
      cache.get("b"); // Miss

      const stats = cache.getStats();
      expect(stats.hits).toBe(2);
      expect(stats.misses).toBe(1);
    });

    it("should calculate hit rate", () => {
      cache.set("a", 1);

      cache.get("a"); // Hit
      cache.get("a"); // Hit
      cache.get("b"); // Miss
      cache.get("c"); // Miss

      expect(cache.getHitRate()).toBe(0.5); // 2/4 = 0.5
    });

    it("should track evictions", () => {
      cache.set("a", 1);
      cache.set("b", 2);
      cache.set("c", 3);
      cache.set("d", 4); // Evicts "a"

      const stats = cache.getStats();
      expect(stats.evictions).toBe(1);
    });

    it("should track size", () => {
      expect(cache.getStats().size).toBe(0);

      cache.set("a", 1);
      expect(cache.getStats().size).toBe(1);

      cache.set("b", 2);
      expect(cache.getStats().size).toBe(2);
    });
  });
});

describe("EmbeddingCache", () => {
  let cache: EmbeddingCache;
  let computeCount = 0;

  beforeEach(() => {
    cache = new EmbeddingCache({
      maxSize: 100,
      ttl: 1000,
    });
    computeCount = 0;
  });

  const mockCompute = async (texts: string[]): Promise<number[][]> => {
    computeCount += texts.length;
    return texts.map((_, i) => [i, i + 1, i + 2]);
  };

  describe("Caching", () => {
    it("should cache embeddings by text", async () => {
      const text = "test embedding";
      const embedding = [1, 2, 3];

      const result1 = await cache.getOrCompute(text, async () => {
        computeCount++;
        return embedding;
      });

      const result2 = await cache.getOrCompute(text, async () => {
        computeCount++;
        return [9, 9, 9]; // Should not be called
      });

      expect(result1).toEqual(embedding);
      expect(result2).toEqual(embedding);
      expect(computeCount).toBe(1); // Only computed once
    });

    it("should handle batch operations", async () => {
      const texts = ["a", "b", "c", "a"]; // "a" is duplicate

      const results = await cache.batchGetOrCompute(texts, mockCompute);

      expect(results).toHaveLength(4);
      expect(computeCount).toBe(3); // Only 3 unique texts
      expect(results[0]).toEqual(results[3]); // "a" should be same
    });

    it("should reuse cached embeddings in batch", async () => {
      // Pre-cache "a"
      await cache.getOrCompute("a", async () => {
        computeCount++;
        return [1, 1, 1];
      });

      expect(computeCount).toBe(1);

      // Batch with "a" and new texts
      const texts = ["a", "b", "c"];
      await cache.batchGetOrCompute(texts, mockCompute);

      expect(computeCount).toBe(1 + 2); // Initial + 2 new
    });
  });

  describe("Statistics", () => {
    it("should track hit rate", async () => {
      await cache.getOrCompute("a", async () => [1]); // Miss
      await cache.getOrCompute("a", async () => [1]); // Hit
      await cache.getOrCompute("a", async () => [1]); // Hit

      const stats = cache.getStats();
      expect(stats.hitRate).toBeCloseTo(2 / 3);
    });

    it("should track size", async () => {
      const stats1 = cache.getStats();
      expect(stats1.size).toBe(0);

      await cache.getOrCompute("a", async () => [1]);
      await cache.getOrCompute("b", async () => [2]);

      const stats2 = cache.getStats();
      expect(stats2.size).toBe(2);
    });
  });

  describe("Cleanup", () => {
    it("should clear cache", async () => {
      await cache.getOrCompute("a", async () => [1]);
      await cache.getOrCompute("b", async () => [2]);

      cache.clear();

      expect(cache.getStats().size).toBe(0);
    });

    it("should cleanup expired", async () => {
      const shortCache = new EmbeddingCache({ ttl: 100 });

      await shortCache.getOrCompute("a", async () => [1]);

      await new Promise(resolve => setTimeout(resolve, 150));

      const cleaned = shortCache.cleanup();
      expect(cleaned).toBe(1);
    });
  });

  describe("Singleton", () => {
    it("should return same instance", () => {
      resetEmbeddingCache();
      const instance1 = getEmbeddingCache();
      const instance2 = getEmbeddingCache();

      expect(instance1).toBe(instance2);
    });

    it("should reset singleton", () => {
      const instance1 = getEmbeddingCache();
      resetEmbeddingCache();
      const instance2 = getEmbeddingCache();

      expect(instance1).not.toBe(instance2);
    });
  });
});

