const DEFAULT_LOCAL_MODEL = "hf:ggml-org/embeddinggemma-300M-GGUF/embeddinggemma-300M-Q8_0.gguf";

/**
 * Wrap provider with LRU cache for embeddings
 */
function withCachedEmbeddings(
  provider: EmbeddingProvider,
  cacheConfig?: { maxSize?: number; ttl?: number }
): EmbeddingProvider {
  const cache = getEmbeddingCache({
    maxSize: cacheConfig?.maxSize ?? 1000,
    ttl: cacheConfig?.ttl ?? 86400000, // 24 hours
  });

  return {
    ...provider,
    embedQuery: async (text: string): Promise<number[]> => {
      return cache.getOrCompute(text, async () => {
        return provider.embedQuery(text);
      });
    },
    embedBatch: async (texts: string[]): Promise<number[][]> => {
      // Batch embed with cache deduplication
      const results: number[][] = new Array(texts.length);
      const uncached: { index: number; text: string }[] = [];

      // Check cache for each text
      for (let i = 0; i < texts.length; i++) {
        const cached = cache.get(texts[i]);
        if (cached) {
          results[i] = cached;
        } else {
          uncached.push({ index: i, text: texts[i] });
        }
      }

      // Batch embed uncached texts
      if (uncached.length > 0) {
        const uncachedTexts = uncached.map((u) => u.text);
        const embeddings = await provider.embedBatch(uncachedTexts);

        // Store in cache and fill results
        for (let i = 0; i < uncached.length; i++) {
          const { index, text } = uncached[i];
          const embedding = embeddings[i] ?? [];
          results[index] = embedding;
          cache.set(text, embedding);
        }
      }

      return results;
    },
  };
}

