    if (id === "local") {
      const provider = await createLocalEmbeddingProvider(options);
      return { provider };
    }
    if (id === "gemini") {
      const { provider, client } = await createGeminiEmbeddingProvider(options);
      return { provider: withCachedEmbeddings(provider), gemini: client };
    }
    if (id === "openrouter") {
      // openrouter uses openai-compatible API; reuse openAi client slot for cache key computation
      const { provider, client } = await createOpenRouterEmbeddingProvider(options);
      return { provider: withCachedEmbeddings(provider), openAi: client };
    }
    const { provider, client } = await createOpenAiEmbeddingProvider(options);
    return { provider: withCachedEmbeddings(provider), openAi: client };
  };

