    clearCaches();
    return {
      wasCompacted: true,
      compactionResult: regularResult,
      reason: "regular",
      tokenCount: regularResult.postCompactTokenCount,
      threshold,
    };
  }

  // Both stages failed
  log.warn("Both compaction methods failed");
  return {
    wasCompacted: false,
    reason: "both methods failed",
    tokenCount: currentTokens,
    threshold,
  };
}

