/**
 * SQLite Performance Optimization Utilities
 * 
 * Applies recommended performance settings for better concurrent access
 * and reduced I/O overhead.
 * 
 * Includes automatic corruption detection and recovery.
 */

import type { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

export interface SqliteOptimizationOptions {
  /** Enable WAL mode for concurrent reads/writes (default: true) */
  walMode?: boolean;
  /** Cache size in KB, negative = KB (default: -262144 = 256MB) */
  cacheSize?: number;
  /** Memory-mapped I/O size in KB (default: 268435456 = 256GB) */
  mmapSize?: number;
  /** Synchronous mode: 0=OFF, 1=NORMAL, 2=FULL (default: 1) */
  synchronous?: number;
  /** Temp store: 0=DEFAULT, 1=FILE, 2=MEMORY (default: 2) */
  tempStore?: number;
  /** Busy timeout in ms (default: 5000) */
  busyTimeout?: number;
  /** Enable automatic corruption recovery (default: true) */
  autoRecover?: boolean;
}

const DEFAULT_OPTIONS: Required<SqliteOptimizationOptions> = {
  walMode: true,
  cacheSize: -262144, // 256MB
  mmapSize: 268435456, // 256GB max
  synchronous: 1, // NORMAL
  tempStore: 2, // MEMORY
  busyTimeout: 5000,
  autoRecover: true,
};

/**
 * Check database integrity using PRAGMA integrity_check
 * 
 * @param db - The DatabaseSync instance to check
 * @returns true if database is healthy, false if corrupted
 */
export function checkDatabaseHealth(db: DatabaseSync): boolean {
  try {
    const result = db.prepare("PRAGMA integrity_check").get() as Record<string, unknown>;
    const status = Object.values(result)[0];
    return status === "ok";
  } catch (error) {
    console.error("[sqlite-utils] Health check failed:", error);
    return false;
  }
}

/**
 * Create a backup of the database file before risky operations
 * 
 * @param dbPath - Path to the database file
 * @returns Path to the backup file, or null if backup failed
 */
export function backupDatabase(dbPath: string): string | null {
  try {
    if (!fs.existsSync(dbPath)) {
      return null;
    }

    const backupPath = `${dbPath}.backup-${Date.now()}`;
    fs.copyFileSync(dbPath, backupPath);

    // Also backup WAL and SHM files if they exist
    const walPath = `${dbPath}-wal`;
    const shmPath = `${dbPath}-shm`;

    if (fs.existsSync(walPath)) {
      fs.copyFileSync(walPath, `${backupPath}-wal`);
    }
    if (fs.existsSync(shmPath)) {
      fs.copyFileSync(shmPath, `${backupPath}-shm`);
    }

    console.log(`[sqlite-utils] Database backed up to ${backupPath}`);
    return backupPath;
  } catch (error) {
    console.error("[sqlite-utils] Backup failed:", error);
    return null;
  }
}

/**
 * Attempt to recover a corrupted database from backup
 * 
 * @param dbPath - Path to the corrupted database
 * @returns true if recovery succeeded, false otherwise
 */
export function recoverDatabase(dbPath: string): boolean {
  try {
    // Find most recent backup
    const dir = path.dirname(dbPath);
    const baseName = path.basename(dbPath);
    const files = fs.readdirSync(dir);

    const backups = files
      .filter(f => f.startsWith(`${baseName}.backup-`))
      .sort()
      .reverse(); // Most recent first

    if (backups.length === 0) {
      console.warn(`[sqlite-utils] No backup found for ${dbPath}`);
      return false;
    }

    const latestBackup = path.join(dir, backups[0]);
    console.log(`[sqlite-utils] Recovering from ${latestBackup}`);

    // Remove corrupted database and its WAL/SHM files
    if (fs.existsSync(dbPath)) fs.unlinkSync(dbPath);
    const walPath = `${dbPath}-wal`;
    const shmPath = `${dbPath}-shm`;
    if (fs.existsSync(walPath)) fs.unlinkSync(walPath);
    if (fs.existsSync(shmPath)) fs.unlinkSync(shmPath);

    // Restore from backup
    fs.copyFileSync(latestBackup, dbPath);

    // Restore WAL/SHM if they exist
    if (fs.existsSync(`${latestBackup}-wal`)) {
      fs.copyFileSync(`${latestBackup}-wal`, walPath);
    }
    if (fs.existsSync(`${latestBackup}-shm`)) {
      fs.copyFileSync(`${latestBackup}-shm`, shmPath);
    }

    console.log(`[sqlite-utils] Database recovered successfully`);
    return true;
  } catch (error) {
    console.error("[sqlite-utils] Recovery failed:", error);
    return false;
  }
}

/**
 * Safely open a database with automatic corruption detection and recovery
 * 
 * @param dbPath - Path to the database file
 * @param DatabaseSync - The DatabaseSync constructor
 * @returns DatabaseSync instance or null if unrecoverable
 */
export function safeOpenDatabase(
  dbPath: string,
  DatabaseSync: new (path: string) => DatabaseSync
): DatabaseSync | null {
  try {
    // Create backup before first open (if database exists)
    if (fs.existsSync(dbPath)) {
      backupDatabase(dbPath);
    }

    // Try to open the database
    const db = new DatabaseSync(dbPath);

    // Check integrity
    if (!checkDatabaseHealth(db)) {
      console.error(`[sqlite-utils] Database ${dbPath} is corrupted`);

      // Close the corrupted database
      try {
        db.close();
      } catch {
        // Ignore close errors
      }

      // Attempt recovery
      if (recoverDatabase(dbPath)) {
        // Try opening again
        const recoveredDb = new DatabaseSync(dbPath);
        if (checkDatabaseHealth(recoveredDb)) {
          console.log(`[sqlite-utils] Database recovered successfully`);
          return recoveredDb;
        } else {
          console.error(`[sqlite-utils] Recovered database still corrupted`);
          try {
            recoveredDb.close();
          } catch {
            // Ignore
          }
        }
      }

      // Recovery failed - recreate from scratch
      console.warn(`[sqlite-utils] Recreating database from scratch: ${dbPath}`);

      // Remove all database files
      if (fs.existsSync(dbPath)) fs.unlinkSync(dbPath);
      const walPath = `${dbPath}-wal`;
      const shmPath = `${dbPath}-shm`;
      if (fs.existsSync(walPath)) fs.unlinkSync(walPath);
      if (fs.existsSync(shmPath)) fs.unlinkSync(shmPath);

      // Create fresh database
      const freshDb = new DatabaseSync(dbPath);
      console.log(`[sqlite-utils] Fresh database created`);
      return freshDb;
    }

    return db;
  } catch (error) {
    console.error(`[sqlite-utils] Failed to open database ${dbPath}:`, error);
    return null;
  }
}

/**
 * Apply performance optimizations to a SQLite database connection.
 * Should be called immediately after opening each database connection.
 * 
 * Now includes automatic health check and recovery.
 * 
 * @param db - The DatabaseSync instance to optimize
 * @param options - Optional customization of optimization settings
 * @returns true if optimizations applied successfully
 */
export function optimizeDatabase(
  db: DatabaseSync,
  options: SqliteOptimizationOptions = {}
): boolean {
  const opts = { ...DEFAULT_OPTIONS, ...options };

  try {
    // Check database health before optimizing
    if (!checkDatabaseHealth(db)) {
      console.error("[sqlite-utils] Database is corrupted, skipping optimizations");
      return false;
    }

    const pragmas: string[] = [];

    if (opts.walMode) {
      pragmas.push(`PRAGMA journal_mode = WAL`);
    }

    pragmas.push(
      `PRAGMA cache_size = ${opts.cacheSize}`,
      `PRAGMA mmap_size = ${opts.mmapSize}`,
      `PRAGMA synchronous = ${opts.synchronous}`,
      `PRAGMA temp_store = ${opts.tempStore}`,
      `PRAGMA busy_timeout = ${opts.busyTimeout}`
    );

    for (const pragma of pragmas) {
      try {
        db.exec(pragma);
      } catch (error) {
        // Log but continue - some pragmas might not be supported
        console.warn(`[sqlite-utils] Failed to apply ${pragma}:`, error);
      }
    }

    return true;
  } catch (error) {
    console.error("[sqlite-utils] Failed to optimize database:", error);
    return false;
  }
}

/**
 * Get the current SQLite optimization settings for debugging.
 * 
 * @param db - The DatabaseSync instance to check
 * @returns Object with current pragma values
 */
export function getDatabaseSettings(db: DatabaseSync): Record<string, unknown> {
  try {
    const settings: Record<string, unknown> = {};

    for (const pragma of [
      "journal_mode",
      "cache_size",
      "mmap_size",
      "synchronous",
      "temp_store",
      "busy_timeout",
    ]) {
      try {
        const result = db.prepare(`PRAGMA ${pragma}`).get() as Record<string, unknown>;
        settings[pragma] = Object.values(result)[0];
      } catch {
        settings[pragma] = "error";
      }
    }

    return settings;
  } catch (error) {
    return { error: String(error) };
  }
}

/**
 * Periodic integrity check for long-running databases
 * Call this periodically (e.g., every hour) to catch corruption early
 * 
 * @param db - The DatabaseSync instance to check
 * @param dbPath - Path to the database file (for recovery)
 * @returns true if healthy, false if corrupted (and recovery attempted)
 */
export function periodicHealthCheck(
  db: DatabaseSync,
  dbPath: string
): boolean {
  const isHealthy = checkDatabaseHealth(db);

  if (!isHealthy) {
    console.error(`[sqlite-utils] Periodic check detected corruption in ${dbPath}`);

    // Attempt recovery
    if (recoverDatabase(dbPath)) {
      console.log(`[sqlite-utils] Database recovered during periodic check`);
      return true;
    } else {
      console.error(`[sqlite-utils] Recovery failed during periodic check`);
      return false;
    }
  }

  return true;
}

/**
 * Clean up old database backups (keep last 5)
 * 
 * @param dbPath - Path to the database file
 * @param keepCount - Number of backups to keep (default: 5)
 */
export function cleanupOldBackups(dbPath: string, keepCount: number = 5): void {
  try {
    const dir = path.dirname(dbPath);
    const baseName = path.basename(dbPath);
    const files = fs.readdirSync(dir);

    const backups = files
      .filter(f => f.startsWith(`${baseName}.backup-`))
      .sort()
      .reverse();

    // Remove old backups
    const toRemove = backups.slice(keepCount);
    for (const backup of toRemove) {
      const backupPath = path.join(dir, backup);
      fs.unlinkSync(backupPath);

      // Also remove associated WAL/SHM backups
      if (fs.existsSync(`${backupPath}-wal`)) fs.unlinkSync(`${backupPath}-wal`);
      if (fs.existsSync(`${backupPath}-shm`)) fs.unlinkSync(`${backupPath}-shm`);
    }

    if (toRemove.length > 0) {
      console.log(`[sqlite-utils] Cleaned up ${toRemove.length} old backup(s)`);
