/**
 * SQLite Performance Optimization Utilities
 * 
 * Applies recommended performance settings for better concurrent access
 * and reduced I/O overhead.
 * 
 * Includes automatic corruption detection and recovery with performance optimizations.
 */

import type { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

export interface SqliteOptimizationOptions {
  /** Enable WAL mode for concurrent reads/writes (default: true) */
  walMode?: boolean;
  /** Cache size in KB, negative = KB (default: -262144 = 256MB) */
  cacheSize?: number;
  /** Memory-mapped I/O size in KB (default: 268435456 = 256GB) */
  mmapSize?: number;
  /** Synchronous mode: 0=OFF, 1=NORMAL, 2=FULL (default: 1) */
  synchronous?: number;
  /** Temp store: 0=DEFAULT, 1=FILE, 2=MEMORY (default: 2) */
  tempStore?: number;
  /** Busy timeout in ms (default: 5000) */
  busyTimeout?: number;
  /** Enable automatic corruption recovery (default: true) */
  autoRecover?: boolean;
}

const DEFAULT_OPTIONS: Required<SqliteOptimizationOptions> = {
  walMode: true,
  cacheSize: -262144, // 256MB
  mmapSize: 268435456, // 256GB max
  synchronous: 1, // NORMAL
  tempStore: 2, // MEMORY
  busyTimeout: 5000,
  autoRecover: true,
};

/**
 * Health check cache - avoid redundant integrity checks
 * Key: dbPath, Value: { healthy: boolean, timestamp: number }
 */
const healthCheckCache = new Map<string, { healthy: boolean; timestamp: number }>();

/** Cache TTL in milliseconds (1 hour) */
const HEALTH_CHECK_CACHE_TTL = 3600000;

/** Minimum time between backups (1 hour) */
const BACKUP_MIN_INTERVAL = 3600000;

/**
 * Quick integrity check using PRAGMA quick_check
 * 10-100x faster than full integrity_check, catches 90%+ of corruption
 * 
 * @param db - The DatabaseSync instance to check
 * @returns true if database is healthy, false if corrupted
 */
export function checkDatabaseHealth(db: DatabaseSync): boolean {
  try {
    const result = db.prepare("PRAGMA quick_check").get() as Record<string, unknown>;
    const status = Object.values(result)[0];
    return status === "ok";
  } catch (error) {
    console.error("[sqlite-utils] Health check failed:", error);
    return false;
  }
}

/**
 * Full integrity check (slower but thorough)
 * Use for periodic background checks, not on every open
 * 
 * @param db - The DatabaseSync instance to check
 * @returns true if database is healthy, false if corrupted
 */
export function checkDatabaseHealthFull(db: DatabaseSync): boolean {
  try {
    const result = db.prepare("PRAGMA integrity_check").get() as Record<string, unknown>;
    const status = Object.values(result)[0];
    return status === "ok";
  } catch (error) {
    console.error("[sqlite-utils] Full health check failed:", error);
    return false;
  }
}

