/**
 * Create a backup of the database file before risky operations
 * Skips backup if last backup is less than 1 hour old (configurable)
 * 
 * @param dbPath - Path to the database file
 * @param minInterval - Minimum milliseconds between backups (default: 1 hour)
 * @returns Path to the backup file, or null if backup skipped/failed
 */
export function backupDatabase(dbPath: string, minInterval: number = BACKUP_MIN_INTERVAL): string | null {
  try {
    if (!fs.existsSync(dbPath)) {
      return null;
    }

    // Check if recent backup exists
    const dir = path.dirname(dbPath);
    const baseName = path.basename(dbPath);
    const files = fs.readdirSync(dir);

    const backups = files
      .filter(f => f.startsWith(`${baseName}.backup-`))
      .map(f => {
        const match = f.match(/\.backup-(\d+)$/);
        return {
          name: f,
          timestamp: match ? parseInt(match[1], 10) : 0,
          path: path.join(dir, f)
        };
      })
      .sort((a, b) => b.timestamp - a.timestamp); // Most recent first

    if (backups.length > 0) {
      const lastBackup = backups[0];
      const age = Date.now() - lastBackup.timestamp;

      if (age < minInterval) {
        console.log(`[sqlite-utils] Skipping backup (last backup ${Math.round(age / 60000)}min ago)`);
        return lastBackup.path;
      }
    }

    const backupPath = `${dbPath}.backup-${Date.now()}`;
    fs.copyFileSync(dbPath, backupPath);

    // Also backup WAL and SHM files if they exist
    const walPath = `${dbPath}-wal`;
    const shmPath = `${dbPath}-shm`;

    if (fs.existsSync(walPath)) {
      fs.copyFileSync(walPath, `${backupPath}-wal`);
    }
    if (fs.existsSync(shmPath)) {
      fs.copyFileSync(shmPath, `${backupPath}-shm`);
    }

    console.log(`[sqlite-utils] Database backed up to ${backupPath}`);

    // Clean up old backups (keep 5)
    cleanupOldBackups(dbPath, 5);

    return backupPath;
  } catch (error) {
    console.error("[sqlite-utils] Backup failed:", error);
    return null;
  }
}

