it("should create dead-letter queue on error", async () => {
  // Create a separate batcher and db for this test to avoid afterEach issues
  const errorDbPath = join(tempDir, "error-test.db");
  const errorDb = new DatabaseSync(errorDbPath);
  errorDb.exec(`
    CREATE TABLE IF NOT EXISTS events (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      source TEXT NOT NULL,
      data TEXT NOT NULL,
      timestamp INTEGER NOT NULL
    )
  `);

  const errorBatcher = new SQLiteEventBatcher(errorDb, {
    maxSize: 5,
    flushIntervalMs: 10000, // Long interval so we control flush
    tableName: "events",
    debug: true
  });

  // Add 5 events
  for (let i = 0; i < 5; i++) {
    errorBatcher.add({
      id: `event-${i}`,
      type: "test",
      source: "test",
      data: JSON.stringify({ index: i }),
      timestamp: Date.now()
    });
  }

  // Close database to force error on flush
  errorDb.close();

  // Trigger flush by adding more events (will fail because db is closed)
  errorBatcher.add({
    id: "event-5",
    type: "test",
    source: "test",
    data: "{}",
    timestamp: Date.now()
  });

  await new Promise(resolve => setTimeout(resolve, 100));

  // Check for dead-letter queue directory
  const dlqPath = join(process.cwd(), "dead-letter-queue");
  expect(existsSync(dlqPath)).toBe(true);

  // Clean up
  errorBatcher.shutdown();
  if (existsSync(dlqPath)) {
    rmSync(dlqPath, { recursive: true, force: true });
  }
});

