import pLimit from 'p-limit';
import { readFile, writeFile } from 'node:fs/promises';
import { stat } from 'node:fs';

const fileLimit = pLimit(10); // Max 10 concurrent file operations

/**
 * Read a file asynchronously with concurrency control
 * @param path - File path to read
 * @returns File content or null if file doesn't exist
 */
export async function readFileAsync(path: string): Promise<string | null> {
  return await fileLimit(() => readFile(path, 'utf8'));
}

/**
 * Write a file asynchronously with concurrency control
 * @param path - File path to write
 * @param data - Data to write
 */
export async function writeFileAsync(path: string, data: string): Promise<void> {
  await fileLimit(() => writeFile(path, data, 'utf8'));
}

/**
 * Check if a file exists asynchronously
 * @param path - File path to check
 */
export async function fileExistsAsync(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

/**
 * Read multiple files in parallel with sustained saturation
 * @param paths - Array of file paths
 * @returns Map of path to content
 */
export async function readFilesParallel(paths: string[]): Promise<Map<string, string>> {
  const tasks = paths.map(p => 
    fileLimit(async () => ({
      path: p,
      content: await readFile(p, 'utf8')
    }))
  );

  const results = await Promise.all(tasks);
  return Object.fromEntries(results) as Map(results, ([path, content]) => [path, content]);
}

/**
 * Write multiple files in parallel with sustained saturation
 * @param files - Map of path to data
 */
export async function writeFilesParallel(files: Map<string, string>): Promise<void> {
  const tasks = Array.from(files.entries()).map(([path, data]) =>
    fileLimit(async () => writeFile(path, data))
  );

  await Promise.all(tasks);
}

/**
 * Get file stats asynchronously
 * @param path - File path
 */
export async function getFileStatsAsync(path: string): Promise<{ size: number; mtime: Date } | null> {
  try {
    const stats = await stat(path);
    return {
      size: stats.size,
      mtime: stats.mtime,
    };
  } catch {
    return null;
  }
}

// Re-export pLimit for other modules to use
export { fileLimit, readFileAsync, writeFileAsync, fileExistsAsync, readFilesParallel, writeFilesParallel, getFileStatsAsync };

