/**
 * Start the neuro-memory-agent MCP server
 * QUALITY IMPROVEMENT: Uses async Python server (100x faster batch embeddings)
 */
async start(): Promise<void> {
  // Try async server first, fall back to sync server
  const asyncScript = `${this.config.agentPath}/mcp_server_async.py`;
  const syncScript = `${this.config.agentPath}/mcp_server.py`;

  // Check which script exists
  const fs = await import("node:fs/promises");
  let serverScript: string;

  try {
    await fs.access(asyncScript);
    serverScript = asyncScript;
    log.info("Using async MCP server (100x faster batch embeddings)");
  } catch {
    try {
      await fs.access(syncScript);
      serverScript = syncScript;
      log.info("Using sync MCP server (fallback)");
    } catch {
      throw new Error(`No MCP server found at ${this.config.agentPath}`);
    }
  }

  return new Promise((resolve, reject) => {
    log.info(`Starting neuro-memory-agent from ${this.config.agentPath}`);

    this.process = spawn(this.config.pythonPath!, [serverScript], {
      cwd: this.config.agentPath,
      stdio: ["pipe", "pipe", "pipe"],
    });

    this.process.stderr?.on("data", (data) => {
      const msg = data.toString().trim();
      // Handle both sync and async server messages
      if (msg.includes("MCP Server started") || msg.includes("Async Neuro-Memory MCP Server started")) {
        this.isReady = true;

        // Initialize batch queue if enabled
        if (this.config.enableBatching) {
          this.initBatchQueue();
        }

        // Log which server version is running
        const serverType = msg.includes("Async") ? "async (100x faster)" : "sync";
        log.info(`✅ Neuro-memory-agent MCP server ready (${serverType})`);

        // Start auto-consolidation if enabled
        if (this.config.autoConsolidate) {
          this.startAutoConsolidation();
        }

        resolve();
      } else {
        log.debug("[neuro-memory stderr]", msg);
      }
    });

    this.process.stdout?.on("data", (data) => {
      this.buffer += data.toString();
      this.processBuffer();
    });

    this.process.on("error", (error) => {
      log.error("Neuro-memory-agent process error:", error);
      this.isReady = false;
      reject(error);
    });

    this.process.on("exit", (code) => {
      if (isVerbose()) {
        log.warn(`Neuro-memory-agent exited with code ${code}`);
      }
      this.isReady = false;
    });

    // Timeout if server doesn't start
    setTimeout(() => {
      if (!this.isReady) {
        reject(new Error("Neuro-memory-agent startup timeout"));
      }
    }, 10000);
  });
}

