private recreateDatabase(): void {
  try {
    log.info("Starting database recreation...");

    // Close existing database connection
    if (this.db) {
      try {
        this.db.close();
      } catch (e) {
        log.debug("Error closing database (expected during recreation):", e);
      }
    }

    // Delete the corrupted database file
    const dbPath = `${process.env.HOME}/.openclaw/tool-analytics.db`;
    try {
      if (fs.existsSync(dbPath)) {
        fs.unlinkSync(dbPath);
        log.info("Deleted corrupted database file");
      }
    } catch (e) {
      log.warn("Could not delete database file:", e);
    }

    // Reopen database (will create fresh file)
    this.db = new DatabaseSync(dbPath);
    optimizeDatabase(this.db);

    // Create schema from scratch
    this.ensureSchema();

    log.info("✅ Analytics database recreated successfully");
  } catch (recreateError) {
    log.error(`Failed to recreate database: ${recreateError instanceof Error ? recreateError.message : String(recreateError)}`);
    log.error("Stack:", recreateError instanceof Error ? recreateError.stack : "N/A");
  }
}

